There is a upstream pending PR (NixOS/nixpkgs#494267) for bun upgrade, here I give a quick workaround for flake project:

```nix
{
  inputs = {
    bun-unstable.url = "github:arch-fan/nixpkgs/bun-1.3.10";
    opencode = {
      url = "github:anomalyco/opencode/v1.2.15";
      inputs.nixpkgs.follows = "bun-unstable";
    };
  };
}
```

Not sure adding a pinned bun version in the flake project is best practice or not, I think adding it here may make build cache invalidated and will fetch bun binary every time even upstream PR merged into the nixpkgs repository.

For what it's worth, I had OpenCode make a plugin for me to do this. Haven't tested it much yet, but here it is:

<details>
<summary>Edit: the code I posted doesn't clean up the block after OpenCode finishes work or exits</summary>

```ts
import type { Plugin } from "@opencode-ai/plugin";
import { spawn, type ChildProcess } from "child_process";

export const SleepInhibitPlugin: Plugin = async () => {
  let inhibitorProcess: ChildProcess | null = null;

  function acquire() {
    if (inhibitorProcess) return;
    inhibitorProcess = spawn(
      "systemd-inhibit",
      [
        "--what=sleep",
        "--who=opencode",
        "--why=AI is actively working",
        "sleep",
        "infinity",
      ],
      { stdio: "ignore" },
    );
    inhibitorProcess.on("exit", () => {
      inhibitorProcess = null;
    });
  }

  function release() {
    if (!inhibitorProcess) return;
    inhibitorProcess.kill();
    inhibitorProcess = null;
  }

  process.on("exit", release);
  process.on("SIGINT", release);
  process.on("SIGTERM", release);

  return {
    event: async ({ event }) => {
      if (
        ["message.updated", "tool.execute.before", "session.updated"].includes(
          event.type,
        )
      ) {
        acquire();
      }
      if (event.type === "session.idle") {
        release();
      }
    },
  };
};
```

</details>

You can run `systemd-inhibit --list --no-pager` while OpenCode is working on something, and you'll see an entry in the list for it.
